const crypto = require('crypto');
const body = $json.body ?? {};
const headers = $json.headers ?? {};
const signature = String(headers['x-mec-signature'] ?? '');
const secret = String($env.N8N_WEBHOOK_SECRET ?? '');
function canonical(value) {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (value && typeof value === 'object') return '{' + Object.keys(value).sort().map(k => JSON.stringify(k) + ':' + canonical(value[k])).join(',') + '}';
  return JSON.stringify(value);
}
let authorized = Boolean(secret && signature);
if (authorized) {
  const expected = crypto.createHmac('sha256', secret).update(canonical(body)).digest('hex');
  const supplied = signature.replace(/^sha256=/, '');
  authorized = expected.length === supplied.length && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(supplied));
}
const gates = body.safety_gates ?? {};
const gatesValid = gates.human_approval_required === true && gates.auto_merge === false && gates.auto_deploy === false && gates.approval_bypass_detected === false;
const correlationValid = Boolean(body.correlation_id && typeof body.correlation_id === 'string');
return [{json: {authorized: authorized && gatesValid && correlationValid, correlation_id: correlationValid ? body.correlation_id : '', safety_gates: gates, rejection_reason: !authorized ? 'WEBHOOK_AUTH_INVALID' : (!gatesValid ? 'SAFETY_GATE_BLOCKED' : (!correlationValid ? 'CORRELATION_ID_REQUIRED' : ''))}}];
